import fs from'node:fs';import path from'node:path';import{createHash}from'node:crypto';import{performance}from'node:perf_hooks';
import{journalLines}from'../live-paper/journal-lines.mjs';import{sealedEnd}from'./replay-dual-no-timelapse-20261005.mjs';import{applyBookPublication,createBookPublicationState}from'../live-paper/book-publication-v2.mjs';
import{BOOK_ALPHA_POLICY,bookFeatures,causalBookLabels,fitBookAlpha,scoreBookAlpha,resetBookEpochs}from'../research/book-alpha-v1.mjs';
const output='data/book-alpha-results-20261006-v1b.json';if(fs.existsSync(output))throw Error('Frozen diagnostic already exists; never overwrite for tuning');const prior=JSON.parse(fs.readFileSync('data/book-alpha-results-20261006-v1.json')),rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),file=path.join(rt,'public-books.jsonl'),end=prior.source.prefixBytes,hash=createHash('sha256'),universe=JSON.parse(fs.readFileSync('live-paper/price-universe.json'));if(sealedEnd(file)<end)throw Error('Original source truncated');let publication=createBookPublicationState(universe),streams=[],active=new Map(),first=null,last=null,bookRows=0;const started=performance.now();
for(const line of journalLines(file,{endByte:end})){hash.update(line+'\n');const row=JSON.parse(line);publication=applyBookPublication(publication,row);if(resetBookEpochs(active,row))continue;const b=row.payload.book,at=Date.parse(row.at),requestAt=Date.parse(b.requestStartedAt);if(at-Date.parse(b.receivedAt)>20000||requestAt>at)continue;let stream=active.get(b.marketId);if(!stream){stream=[];active.set(b.marketId,stream);streams.push(stream);}const features=bookFeatures(b,stream.at(-1));if(!features)continue;stream.push({...features,marketId:b.marketId,exchangeId:b.exchangeId,at,requestAt,sequence:row.sequence});first??=at;last=at;bookRows++;}
if(first===null||last<=first)throw Error('Missing source chronology');const cutoff=Math.floor(first+(last-first)*BOOK_ALPHA_POLICY.trainFraction),results=[];for(const horizonMs of BOOK_ALPHA_POLICY.horizonsMs){const labels=causalBookLabels(streams,horizonMs);try{const model=fitBookAlpha(labels,cutoff);results.push({horizonMs,labels:labels.length,model,score:scoreBookAlpha(model,labels,streams.flat())});}catch(e){if(!String(e).includes('INSUFFICIENT_CHRONOLOGY'))throw e;results.push({horizonMs,labels:labels.length,unavailable:'insufficient_chronological_labels'});}}
const sourceSha=hash.digest('hex');if(sourceSha!==prior.source.sha256)throw Error('Original diagnostic source changed');const out={schemaVersion:1,at:new Date().toISOString(),policy:BOOK_ALPHA_POLICY,correction:{priorResult:'book-alpha-results-20261006-v1.json',priorUsable:false,reason:'Global invalidation must clear every feature/label epoch; earlier driver deleted only a null map key.',sameSourcePrefix:true,policyTuned:false},source:{prefixBytes:end,sha256:sourceSha,sequence:publication.sequence,tailHash:publication.hash,first:new Date(first).toISOString(),last:new Date(last).toISOString(),hours:(last-first)/3600000,bookRows,streams:streams.length},cutoff:new Date(cutoff).toISOString(),wallMs:performance.now()-started,results,accountRequests:0,acceptedOrders:0,realizedPnl:null,profitabilityEstablished:false,limitations:['Quote-only diagnostic has no funded wallet, order acceptance or queue proof; observed margins are not P&L.','Only later independently requested depth-qualified receipts label outcomes; missing horizons/depth/limit fills are censored.','Training uses labels already available at cutoff; subsequent fitting segment is chronological but this capture has been examined in other development research.','Repeated receipts and overlapping labels/related elections are correlated, not independent statistical samples.','All three fixed horizons are retained, not a selected winner; new prospective frozen evidence is required.']};fs.writeFileSync(output,JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({hours:out.source.hours,bookRows,wallMs:out.wallMs,results:results.map(r=>({horizonMs:r.horizonMs,labels:r.labels,training:r.model?.trainLabels,later:r.score?.laterLabels,rmse:r.score?.rmse,baseline:r.score?.unchangedBidRmse,selected:r.score?.selectedQuoteSignals,unavailable:r.unavailable})),profitabilityEstablished:false}));
